  1746  /**
  1747   * g_uri_parse_params:
  1748   * @params: a `%`-encoded string containing "attribute=value"
  1749   *   parameters
  1750   * @length: the length of @params, or -1 if it is NUL-terminated
  1751   * @separator: the separator character between parameters.
  1752   *   (usually ';', but sometimes '&')
  1753   * @case_insensitive: whether parameter names are case insensitive
  1754   *
  1755   * Many URI schemes include one or more attribute/value pairs as part of the URI
  1756   * value. This method can be used to parse them into a hash table.
  1757   *
  1758   * The @params string is assumed to still be `%`-encoded, but the returned
  1759   * values will be fully decoded. (Thus it is possible that the returned values
  1760   * may contain '=' or @separator, if the value was encoded in the input.)
  1761   * Invalid `%`-encoding is treated as with the non-%G_URI_FLAGS_PARSE_STRICT
  1762   * rules for g_uri_parse(). (However, if @params is the path or query string
  1763   * from a #GUri that was parsed with %G_URI_FLAGS_PARSE_STRICT and
  1764   * %G_URI_FLAGS_ENCODED, then you already know that it does not contain any
  1765   * invalid encoding.)
  1766   *
  1767   * Return value: (transfer full) (element-type utf8 utf8): a hash table of
  1768   * attribute/value pairs. Both names and values will be fully-decoded. If
  1769   * @params cannot be parsed (eg, it contains two @separator characters in a
  1770   * row), then %NULL is returned.
  1771   *
  1772   * Since: 2.66
  1773   */
  1774  GHashTable *
  1775  g_uri_parse_params (const gchar     *params,
  1776                      gssize           length,
  1777                      gchar            separator,
  1778                      gboolean         case_insensitive)
  1779  {
  1780    GHashTable *hash;
  1781    const gchar *end, *attr, *attr_end, *value, *value_end;
  1782    gchar *decoded_attr, *decoded_value;
  1783
  1784    g_return_val_if_fail (params != NULL, NULL);
  1785    g_return_val_if_fail (length >= -1, NULL);
  1786
  1787    if (case_insensitive)
  1788      {
  1789        hash = g_hash_table_new_full (str_ascii_case_hash,
  1790                                      str_ascii_case_equal,
  1791                                      g_free, g_free);
  1792      }
  1793    else
  1794      {
  1795        hash = g_hash_table_new_full (g_str_hash, g_str_equal,
  1796                                      g_free, g_free);
  1797      }
  1798
  1799    if (length == -1)
  1800      end = params + strlen (params);
  1801    else
  1802      end = params + length;
  1803
  1804    attr = params;
  1805    while (attr < end)
  1806      {
  1807        value_end = memchr (attr, separator, end - attr);
  1808        if (!value_end)
  1809          value_end = end;
  1810
  1811        attr_end = memchr (attr, '=', value_end - attr);
  1812        if (!attr_end)
  1813          {
  1814            g_hash_table_destroy (hash);
  1815            return NULL;
  1816          }
  1817        if (!uri_decode (&decoded_attr, attr, attr_end - attr,
  1818                         0, G_URI_ERROR_MISC, NULL))
  1819          {
  1820            g_hash_table_destroy (hash);
  1821            return NULL;
  1822          }
  1823
  1824        value = attr_end + 1;
  1825        if (!uri_decode (&decoded_value, value, value_end - value,
  1826                         0, G_URI_ERROR_MISC, NULL))
  1827          {
  1828            g_free (decoded_attr);
  1829            g_hash_table_destroy (hash);
  1830            return NULL;
  1831          }
  1832
  1833        g_hash_table_insert (hash, decoded_attr, decoded_value);
  1834        attr = value_end + 1;
  1835      }
  1836
  1837    return hash;
  1838  }
